/* mg-villages-active */ SELECT COUNT(DISTINCT village_code) AS villages_with_activity
FROM (SELECT village_code FROM curated.v_employment
      UNION SELECT village_code FROM curated.v_expenditure) AS v;

SELECT SUM(person_days) AS person_days FROM curated.v_employment

/* metric:cm_elevate_disb_beneficiaries total */ SELECT COUNT(DISTINCT application_number) AS beneficiaries
FROM curated.v_cm_elevate_disbursement
WHERE year_key = 2024

SELECT NULL::text AS k, (SUM(households_employed))::float8 AS ben, (COUNT(DISTINCT village_code))::float8 AS villages, (COUNT(DISTINCT lgd_district))::float8 AS districts, (COUNT(DISTINCT lgd_block))::float8 AS blocks FROM curated.v_employment WHERE TRUE
;
SELECT NULL::text AS k, (SUM(total_exp) / 100.0)::float8 AS money FROM curated.v_expenditure WHERE TRUE
;
SELECT NULL::text AS k, (COUNT(*))::float8 AS ben, (COUNT(*) FILTER (WHERE is_completed))::float8 AS completed, (SUM(amount_released) / 1e7)::float8 AS money, (SUM(sanctioned_amount) / 1e7)::float8 AS sanctioned, (COUNT(DISTINCT village_code))::float8 AS villages, (COUNT(DISTINCT lgd_district))::float8 AS districts, (COUNT(DISTINCT lgd_block))::float8 AS blocks FROM curated.v_pmay WHERE TRUE

/* metric:mgnrega_total_expenditure breakdown */ SELECT year_key, MAX(financial_year_short) AS financial_year, ROUND((SUM(total_exp))::numeric, 2) AS total_expenditure_lakh
FROM curated.v_expenditure
GROUP BY year_key ORDER BY year_key
